def fusion_classements(a, b):
    resultat = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i][1] >= b[j][1]:
            resultat.append(a[i])
            i += 1
        else:
            resultat.append(b[j])
            j += 1
